#!/usr/bin/env sh
# Stills, words only on top of SolidCraft's renders (video/make_frames.py) and our drawings of the USGS grid
# (video/map_png.py). Needs ffmpeg + DejaVu fonts (the video-qa image):
#   docker run --rm -v <lab>:/work -w /work video-qa:2 sh video/make_hook.sh
#   hook-landscape.png  the slices lofted as drawn (under the floor) and right way up; content scaled to 88% inside a
#                       margin, so the 5 s push-in of the hook overlay never crops the headline
#   twist.png           our relief of the grid, north up, and the same grid mirrored north-south (what the turned-over
#                       tile measures as: top at y 70.1, not 44.7), crater openings labelled
#   stretch.png         1x and 2x height, SolidCraft renders
#   hook-vertical.png   the Short's frame 0: 1x vs 2x
set -eu
F=video/frames
B=/usr/share/fonts/truetype/dejavu/DejaVuSans-Bold.ttf
R=/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf
RED=0xb71c1c; GREEN=0x1b5e20; INK=0x1f2937; GREY=0x475569
ffmpeg -v error -y -i $F/side-under-floor.png -i $F/side-upright.png -filter_complex "[0:v]crop=1440:380:240:420[a];[1:v]crop=1440:380:240:210[b];color=c=0xeceff4:s=1920x1080[bg];[bg][a]overlay=240:95[t];[t][b]overlay=240:575,drawtext=fontfile=$B:text='✗ UNDER THE FLOOR':fontcolor=$RED:fontsize=54:x=240:y=22,drawtext=fontfile=$R:text='SolidCraft said ok\: true':fontcolor=$INK:fontsize=36:x=w-text_w-240:y=34,drawtext=fontfile=$B:text='✓ RIGHT WAY UP':fontcolor=$GREEN:fontsize=54:x=240:y=500,drawtext=fontfile=$R:text='floor':fontcolor=$GREY:fontsize=30:x=1700:y=168,drawtext=fontfile=$R:text='floor':fontcolor=$GREY:fontsize=30:x=1700:y=876,drawtext=fontfile=$R:text='Mount St. Helens from USGS data · 50 slices lofted · SolidCraft 0.19.0 renders · dark line\: a floor plate we added':fontcolor=$INK:fontsize=26:x=(w-text_w)/2:y=1030,scale=1690:950,pad=1920:1080:115:65:color=0xeceff4" -frames:v 1 $F/hook-landscape.png
ffmpeg -v error -y -i $F/data-relief.png -i $F/data-relief-mirrored.png -filter_complex "[0:v]scale=820:656[a];[1:v]scale=820:656[b];color=c=0xffffff:s=1920x1080[bg];[bg][a]overlay=110:190[t];[t][b]overlay=990:190,drawbox=x=110:y=190:w=820:h=656:color=0xd1d5db:t=3,drawbox=x=990:y=190:w=820:h=656:color=0xd1d5db:t=3,drawtext=fontfile=$B:text='✓ RIGHT WAY ROUND':fontcolor=$GREEN:fontsize=50:x=110+(820-text_w)/2:y=40,drawtext=fontfile=$B:text='✗ TURNED OVER\: A MIRROR':fontcolor=$RED:fontsize=50:x=990+(820-text_w)/2:y=40,drawtext=fontfile=$B:text='N ↑':fontcolor=$INK:fontsize=72:x=24:y=200,drawtext=fontfile=$B:text='▲ crater opens north':fontcolor=$GREEN:fontsize=40:x=110+(820-text_w)/2:y=120,drawtext=fontfile=$B:text='▼ crater opens south':fontcolor=$RED:fontsize=40:x=990+(820-text_w)/2:y=870,drawtext=fontfile=$R:text='Seen from above with north up · our drawing of the USGS heights · right panel mirrored north to south as the turned-over tile measures':fontcolor=$INK:fontsize=24:x=(w-text_w)/2:y=1035" -frames:v 1 $F/twist.png
ffmpeg -v error -y -i $F/iso-1x.png -i $F/iso-2x.png -filter_complex "[0:v]crop=1200:760:360:180,scale=900:-2[a];[1:v]crop=1200:760:360:180,scale=900:-2[b];color=c=0xeceff4:s=1920x1080[bg];[bg][a]overlay=40:200[t];[t][b]overlay=980:200,drawtext=fontfile=$B:text='TRUE HEIGHT (1x)':fontcolor=$INK:fontsize=56:x=40+(900-text_w)/2:y=80,drawtext=fontfile=$B:text='TWICE AS TALL (2x)':fontcolor=$INK:fontsize=56:x=980+(900-text_w)/2:y=80,drawtext=fontfile=$R:text='The same 50 slices · SolidCraft 0.19.0 renders · the lab STL is 1.5x':fontcolor=$INK:fontsize=30:x=(w-text_w)/2:y=1010" -frames:v 1 $F/stretch.png
ffmpeg -v error -y -i $F/iso-1x.png -i $F/iso-2x.png -filter_complex "[0:v]crop=1200:760:360:180,scale=1000:-2[a];[1:v]crop=1200:760:360:180,scale=1000:-2[b];color=c=0xeceff4:s=1080x1920[bg];[bg][a]overlay=40:260[t];[t][b]overlay=40:1120,drawtext=fontfile=$B:text='TRUE HEIGHT (1x)':fontcolor=$INK:fontsize=64:x=(w-text_w)/2:y=150,drawtext=fontfile=$B:text='TWICE AS TALL (2x)':fontcolor=$INK:fontsize=64:x=(w-text_w)/2:y=1010,drawtext=fontfile=$R:text='Mount St. Helens, USGS data · SolidCraft renders':fontcolor=$INK:fontsize=34:x=(w-text_w)/2:y=1850" -frames:v 1 $F/hook-vertical.png
echo "wrote hook-landscape.png twist.png stretch.png hook-vertical.png"
